namespace PhysioBoo.Application.ViewModels.Conversations
{
    public sealed record OpenDirectConversationViewModel(Guid UserId);

    // Id is generated by the client: sending again with the same id returns the stored message instead of a duplicate.
    public sealed record SendConversationMessageViewModel(Guid Id, string? Content);

    // The newest message the reader has actually seen; everything up to it becomes read.
    public sealed record MarkConversationReadViewModel(Guid MessageId);
}
